//! Raw info-span slicing and v1/v2 infohashes of a hybrid .torrent.
//!
//! The fixture was generated by the official BEP-52/BEP-47 creator
//! algorithm (stdlib-only, reproducible; see tests/fixtures/README.md) and
//! parse-verified against libtorrent 2.1.1.0 (the qBittorrent engine) —
//! the expected values asserted here are the info_hashes that engine
//! produced, hence "matches qBittorrent".
//!
//! Rule (SPEC §4.1 / BEP-52): the infohash must be computed over the raw
//! byte slice of the metadata's info section; decode->re-encode
//! recomputation is forbidden.

use std::fs;
use std::path::Path;

use taiji_bt::bencode::{Value, decode_with_info_span};
// sha1/sha2 0.11 share one digest::Digest trait, so a single import path
// suffices
use sha1::{Digest as _, Sha1};
use sha2::Sha256;

const EXPECTED_V1: &str = "9e4fb011b72c9ebdf1152175a20fe4e9f5a866a0";
const EXPECTED_V2: &str = "d7f59962f0b19ab34dbad44ea906d9f270806fedab6eff552ebef9cfa8f8cb40";

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn get<'a>(value: &'a Value, key: &[u8]) -> &'a Value {
    match value.get(key) {
        Some(v) => v,
        None => panic!("missing dict key {key:?}"),
    }
}

#[test]
fn hybrid_fixture_info_hashes_match_libtorrent() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/hybrid_16k.torrent");
    let torrent = match fs::read(&path) {
        Ok(b) => b,
        Err(e) => panic!("read fixture {path:?}: {e}"),
    };

    let (value, span) = match decode_with_info_span(&torrent) {
        Ok(x) => x,
        Err(e) => panic!("decode_with_info_span failed: {e:?}"),
    };
    // the info-span range recorded by the generator
    assert_eq!(span, 51..557);

    // v1 = SHA-1 of the raw info slice, v2 = SHA-256 of the raw info
    // slice, per BEP-52
    let v1 = Sha1::digest(&torrent[span.clone()]);
    let v2 = Sha256::digest(&torrent[span]);
    assert_eq!(
        hex(&v1),
        EXPECTED_V1,
        "v1 infohash (SHA-1 of raw info span)"
    );
    assert_eq!(
        hex(&v2),
        EXPECTED_V2,
        "v2 infohash (SHA-256 of raw info span)"
    );

    // ---- content sanity: required hybrid metadata structure
    // (BEP-52/BEP-47) ----
    let info = get(&value, b"info");
    assert_eq!(get(info, b"meta version"), &Value::Int(2));
    assert_eq!(
        get(info, b"name"),
        &Value::Bytes(b"taiji-p01-hybrid".to_vec())
    );

    // file tree: two real files, leaves {"": {length, pieces root}}
    let tree = get(info, b"file tree");
    let leaf_a = get(get(tree, b"a.bin"), b"");
    assert_eq!(get(leaf_a, b"length"), &Value::Int(70000));
    let root_a = match get(leaf_a, b"pieces root") {
        Value::Bytes(b) => b.clone(),
        v => panic!("pieces root not bytes: {v:?}"),
    };
    assert_eq!(root_a.len(), 32);
    let leaf_b = get(get(tree, b"b.bin"), b"");
    assert_eq!(get(leaf_b, b"length"), &Value::Int(30000));
    let root_b = match get(leaf_b, b"pieces root") {
        Value::Bytes(b) => b.clone(),
        v => panic!("pieces root not bytes: {v:?}"),
    };
    assert_eq!(root_b.len(), 32);
    // pad files exist only in the v1 files list, never the file tree
    // (BEP-47/SPEC §4.2)
    assert_eq!(tree.get(b".pad"), None);

    // v1 files list: a.bin + .pad/11920(attr=p) + b.bin
    let files = match get(info, b"files") {
        Value::List(l) => l,
        v => panic!("files not a list: {v:?}"),
    };
    assert_eq!(files.len(), 3);
    let pad = get(&files[1], b"path");
    assert_eq!(
        pad,
        &Value::List(vec![
            Value::Bytes(b".pad".to_vec()),
            Value::Bytes(b"11920".to_vec()),
        ])
    );
    assert_eq!(get(&files[1], b"attr"), &Value::Bytes(b"p".to_vec()));

    // top-level piece layers (outside info): keys are raw 32B roots
    // (BEP-52: hashes are always stored binary), values are the
    // one-hash-per-piece layer (160B = 5 pieces, 64B = 2 pieces)
    let layers = get(&value, b"piece layers");
    let layer_a = match get(layers, &root_a) {
        Value::Bytes(b) => b,
        v => panic!("piece layer not bytes: {v:?}"),
    };
    assert_eq!(
        layer_a.len(),
        160,
        "a.bin piece layer: 5 x 32B piece hashes"
    );
    let layer_b = match get(layers, &root_b) {
        Value::Bytes(b) => b,
        v => panic!("piece layer not bytes: {v:?}"),
    };
    assert_eq!(layer_b.len(), 64, "b.bin piece layer: 2 x 32B piece hashes");
}
